<script lang="ts">
 import {onMount} from 'svelte';
 import type {TitleDetail} from '../../catalog/application/catalog';
 import type {ReadingGateway,Selection} from '../application/progress';
 let {title,readingGateway}:{title:TitleDetail;readingGateway:ReadingGateway}=$props();
 let account=$state<string|null>(null),selection=$state<Selection>({titleId:'',status:'reading',favorite:false,preferredTeamId:'',notify:true}),busy=$state(true),message=$state(''),resume=$state('');
 onMount(()=>{void(async()=>{try{account=await readingGateway.account();if(account){const item=await readingGateway.selection(account,title.id);if(item){selection={...item};resume=item.progress.releaseId;}}selection.titleId=title.id;}catch{message='Кітапхана деректерін жүктеу мүмкін болмады';}finally{busy=false;}})();});
 async function save(){if(!account)return;busy=true;try{await readingGateway.save(account,selection);message='Кітапханаға сақталды';}catch(failure){message=failure instanceof Error?failure.message:'Сақтау мүмкін болмады';}finally{busy=false;}}
</script>
<section class="selection"><h2>Менің кітапханам</h2>{#if busy}<p role="status">Жүктелуде…</p>{:else if account}<form onsubmit={event=>{event.preventDefault();void save();}}><label>Оқу мәртебесі<select bind:value={selection.status}><option value="reading">Оқып жүрмін</option><option value="planned">Жоспарда</option><option value="completed">Оқып болдым</option><option value="paused">Үзілісте</option><option value="dropped">Тоқтаттым</option></select></label><label>Қалаған аударма тобы<select bind:value={selection.preferredTeamId}><option value="">Таңдалмаған</option>{#each title.projects as project}<option value={project.teamId}>{project.teamName}</option>{/each}</select></label><label class="check"><input type="checkbox" bind:checked={selection.favorite}/>Таңдаулы</label><label class="check"><input type="checkbox" bind:checked={selection.notify}/>Жаңа тараулар туралы хабарлау</label><button class="button primary" disabled={busy}>Сақтау</button>{#if resume}<a class="button subtle" href={`/read/${resume}`}>Оқуды жалғастыру</a>{/if}</form>{:else}<p class="muted">Оқу орны қонақ ретінде де құрылғыда сақталады. Кітапхана үшін <a class="auth-link" href="/login">кіріңіз</a>.</p>{/if}{#if message}<p role="status">{message}</p>{/if}</section>
<style>.selection{border-block:1px solid var(--line);margin-top:24px;padding:20px 0}.selection h2{font-size:20px;margin-bottom:16px}form{display:flex;flex-wrap:wrap;align-items:end;gap:12px}label{display:grid;gap:8px;font-size:13px;flex:1 1 200px}.check{display:flex;align-items:center;min-height:44px;gap:8px}.check input{width:20px;height:20px;min-height:20px}</style>
